beforeSaveCustomScript:
ifThen(!name, name = string\concatenate('Contract - ', unit.name, ' - ', contact.name));
remainingAmount = totalAmount - ifThenElse(downPayment, downPayment, 0);
remainingAmountCurrency = totalAmountCurrency;
ifThen(unitId && status == 'Active', record\update('Unit', unitId, 'status', 'Contracted'));
ifThen(unitId && status == 'Completed', record\update('Unit', unitId, 'status', 'Sold', 'buyerId', contactId, 'soldDate', ifThenElse(contractDate, contractDate, datetime\today())));
